function normalizeTimer(st){const m=st.meditation;if(m.running&&m.lastTick){const elapsed=Math.max(0,Math.floor((Date.now()-m.lastTick)/1000));if(elapsed){m.remaining=Math.max(0,(m.remaining??900)-elapsed);m.lastTick=Date.now();if(m.remaining===0){m.running=false;if(m.date){st.firstSaturday.checks=st.firstSaturday.checks||{};st.firstSaturday.checks[m.date]={...(st.firstSaturday.checks[m.date]||{}),meditation:true}}save(st)}}}return st}
